class Solution {
public:
    vector<int> numMovesStones(int a, int b, int c) {
        vector<int> x = {a, b, c};
        sort(x.begin(), x.end());
        int left = x[1] - x[0], right = x[2] - x[1];
        int minimum = (left == 1 && right == 1) ? 0 :
                      (left <= 2 || right <= 2 ? 1 : 2);
        return {minimum, x[2] - x[0] - 2};
    }
};
